  FT["BN-S-10-2007-E-ANTIQUITIES-AND-TREASURE-TROVE-ANCIENT-MO-C0F485"] = {"id":"BN-S-10-2007-E-ANTIQUITIES-AND-TREASURE-TROVE-ANCIENT-MO-C0F485","coverage":"full","language":"en","sourceName":"Attorney General's Chambers, Brunei Darussalam (AGC) — LAWS OF BRUNEI / Government Gazette","sourceUrl":"","fetchedAt":"2026-10-09","articleCount":2,"structureMode":"SECTION","title":{"zh":"古物与埋藏宝物（古代遗迹与历史遗址）命令 2007","en":"ANTIQUITIES AND TREASURE TROVE ANCIENT MONUMENTS AND HISTORICAL SITES ORDER 2007","orig":"ANTIQUITIES AND TREASURE TROVE ANCIENT MONUMENTS AND HISTORICAL SITES ORDER 2007","vi":"Sắc lệnh Cổ vật, kho báu, di tích cổ và di tích lịch sử năm 2007","th":"คำสั่งโบราณวัตถุ สมบัติโบราณ อนุสาวรีย์โบราณ และแหล่งประวัติศาสตร์ พ.ศ. 2550","id":"Perintah Benda Cagar Budaya, Harta Karun, Monumen Kuno, dan Situs Sejarah Tahun 2007","ms":"Perintah Antikuiti, Harta Karun, Monumen Purba dan Tapak Sejarah 2007"},"level":"regulation","status":"active","docNumber":"S 10/2007","issuingBody":"Attorney General's Chambers, Brunei Darussalam","promulgatedDate":"2007","completenessNote":"来源为 AGC 官方 PDF《S-10_2007_E-ANTIQUITIES-AND-TREASURE-TROVE-ANCIENT-MONUMENTS-AND-HISTORICAL-SITES-ORDER-2007.pdf》（3 页），本次切分 2 条。该 PDF 为扫描件 + OCR 文本层，正文按版式位置重建：已剔除页眉页脚与边栏条标题、回接折行；未改写措辞、未增删内容。OCR 层面可能存在个别粘连或形近字，逐字引用请以原始 PDF 为准。","textQuality":"ocr-scanned","sourceFile":"S-10_2007_E-ANTIQUITIES-AND-TREASURE-TROVE-ANCIENT-MONUMENTS-AND-HISTORICAL-SITES-ORDER-2007.pdf","country":"BN","countryName":"文莱","layer":"intl","articles":[{"id":"BN-S-10-2007-E-ANTIQUITIES-AND-TREASURE-TROVE-ANCIENT-MO-C0F485-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"This Order may be cited as the Antiquities and 'freasure 'frove (Ancient · Monuments and Historical Sites) Order, 2007. Publication of schedule of ancient monuments and historical sites."}},{"id":"BN-S-10-2007-E-ANTIQUITIES-AND-TREASURE-TROVE-ANCIENT-MO-C0F485-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Publication of schedule of ancient monuments and historical sites.\n\nSCHEDULE\n\nBRUNEI DARUSSALAM GOVERNMENT GAZETTE ANTIQUITIES AND TREASURE TROVE (ANCIENT MONUMENTS AND HISTORICAL SITES) ORDER, 2007 In exercise of the power conferred by section 17(2) of the Antiquities and Treasure 'frove Act, the Director of Museums, on the direction of and with the approval of His Majesty the Sultan and Yang Di-Pertuan in Council, hereby publishes the following Order - Citation."}}],"pack":"bn-p13","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1801-BN-1261","source":"ANTIQUITIES AND TREASURE TROVE ANCIENT MONUMENTS AND HISTORICAL SITES ORDER 2007","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["BN-S-10-2011-WHOLESOME-MEAT-FEES-REGULATIONS-2011"] = {"id":"BN-S-10-2011-WHOLESOME-MEAT-FEES-REGULATIONS-2011","coverage":"full","language":"en","sourceName":"Attorney General's Chambers, Brunei Darussalam (AGC) — LAWS OF BRUNEI / Government Gazette","sourceUrl":"","fetchedAt":"2026-10-09","articleCount":6,"structureMode":"SECTION","title":{"zh":"卫生肉类费用条例 2011","en":"WHOLESOME MEAT FEES REGULATIONS 2011","orig":"WHOLESOME MEAT FEES REGULATIONS 2011","vi":"Quy định Thịt an toàn: lệ phí năm 2011","th":"ข้อบังคับเนื้อสัตว์ปลอดภัย: ค่าธรรมเนียม พ.ศ. 2554","id":"Peraturan Daging Sehat: Biaya Tahun 2011","ms":"Peraturan Daging Bersih: Fi 2011"},"level":"regulation","status":"active","docNumber":"S 10/2011","issuingBody":"Attorney General's Chambers, Brunei Darussalam","promulgatedDate":"2011","completenessNote":"来源为 AGC 官方 PDF《S-10-2011-WHOLESOME-MEAT-FEES-REGULATIONS-2011.pdf》（4 页），本次切分 6 条。该 PDF 为扫描件 + OCR 文本层，正文按版式位置重建：已剔除页眉页脚与边栏条标题、回接折行；未改写措辞、未增删内容。OCR 层面可能存在个别粘连或形近字，逐字引用请以原始 PDF 为准。","textQuality":"ocr-scanned","sourceFile":"S-10-2011-WHOLESOME-MEAT-FEES-REGULATIONS-2011.pdf","country":"BN","countryName":"文莱","layer":"intl","articles":[{"id":"BN-S-10-2011-WHOLESOME-MEAT-FEES-REGULATIONS-2011-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"These Regulations may be cited as the Wholesome Meat (Fees) Regulations, 2011 and shall commence on the same date as the Wholesome Meat Order, 2011. Fees."}},{"id":"BN-S-10-2011-WHOLESOME-MEAT-FEES-REGULATIONS-2011-A2","no":2,"noLabel":{"en":"Section 2."},"heading":{"en":"In exercise of the power conferred by section 38{2) of the Wholesome Meat"},"text":{"en":"The fees specified in the Schedule shall be payable in respect of the services or matters set out opposite thereto. SCHEDULE {regulation 2)\n\nFEES FOR LICENCES AND PERMITS UNDER PART II OF ORDER Description of licence or permit Provision under which Fee payable licence or permit is issued Permit to export meat products Section 6 $3 per permit\n\nFEES FOR LICENCES AND PERMIT UNDER PART III OF ORDER Description of licence or permit Provision under Fee payable which licence or permit is issued L Licence to operate a Section 11(1){a} $500 per annum slaughtering centre for poultry"}},{"id":"BN-S-10-2011-WHOLESOME-MEAT-FEES-REGULATIONS-2011-A3","no":3,"noLabel":{"en":"Section 3."},"chapter":{"en":"PART II"},"text":{"en":"Renewal of licence to Section 11(7)(c} $250 per annum operate a slaughtering centre for poultry"}},{"id":"BN-S-10-2011-WHOLESOME-MEAT-FEES-REGULATIONS-2011-A4","no":4,"noLabel":{"en":"Section 4."},"chapter":{"en":"PART II"},"text":{"en":"Renewal of licence to Section 11(7){c} $250 per annum operate a slaughtering centre for livestock"}},{"id":"BN-S-10-2011-WHOLESOME-MEAT-FEES-REGULATIONS-2011-A5","no":5,"noLabel":{"en":"Section 5."},"chapter":{"en":"PART II"},"text":{"en":"Permit to slaughter cattle, Section 11(1){b} $25 per permit plus buffaloes, horses and a fee of $10 per camels other than at animal slaughtered licensed slaughtering centre"}},{"id":"BN-S-10-2011-WHOLESOME-MEAT-FEES-REGULATIONS-2011-A6","no":6,"noLabel":{"en":"Section 6."},"chapter":{"en":"PART II"},"text":{"en":"Permit to slaughter goats, Section 11(1)/b} $15 per permit plus sheep and small ruminants fee of $5 per animal other than at licensed slaughtered slaughtering centre\n\nFEES FOR EXPORT HEALTH CERTIFICATES Description of licence or permit Provision under which Fee payable licence or permit is issued Health certificate for export of Regulation 8 of the $10 per certificate meat product Wholesome Meat (Import, Export and Transhipment) Regulations, 2011\n\nGENERAL Description of matter in respect of which fee is payable Fee payable For a certified true copy of any licence, permit, certificate $5.00 or other document issued by the Director under the Order or any of the regulations, or for the endorsement of certification by the Director of any document used in connection with the export of the meat products Made this 28th. day of Safar, 1432 Hijriah corresponding to the 2nd. day of February, 2011.\n\nPERIN ORANG KAYA SERI UTAMA DATO SERI SETIA\n\nA WANG HAJI YAHYA BIN BEGAWAN MUDIM\n\nDATO PADUKA HAJI BAKAR Minister of Industry and Primary Resources, Brunei Darussalam."}}],"pack":"bn-p13","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1801-BN-1261","source":"WHOLESOME MEAT FEES REGULATIONS 2011","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
